import { useEffect, useState } from 'react';
import { FileDown } from 'lucide-react';

interface Item {
  file: string;
  title: string;
  description: string;
  pages: number;
  bytes: number;
  master: boolean;
}

/** Lists the PDFs generated by `npm run pdf` (public/downloads/manifest.json). Honest when they are absent. */
export function DownloadsCard({ compact = false }: { compact?: boolean }) {
  const [items, setItems] = useState<Item[] | null | undefined>(undefined);
  useEffect(() => {
    fetch('./downloads/manifest.json')
      .then((r) => (r.ok ? r.json() : null))
      .then((j) => setItems(j?.files ?? null))
      .catch(() => setItems(null));
  }, []);
  const mb = (b: number) => (b > 1_000_000 ? `${(b / 1_000_000).toFixed(1)} MB` : `${Math.round(b / 1000)} KB`);

  return (
    <section className="card p-5">
      <h2 className="mb-1 flex items-center gap-2 font-semibold">
        <FileDown className="h-4 w-4 text-brand-600" /> Downloadable study guides (PDF)
      </h2>
      <p className="mb-3 text-sm text-slate-600 dark:text-slate-400">
        Generated from the same lesson data as this site. Print them or read offline.
      </p>
      {items === undefined && <div className="text-sm text-slate-500">Checking…</div>}
      {items === null && (
        <div className="rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm text-amber-900 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-200">
          The PDFs have not been generated on this machine yet. Run <code className="font-mono">npm run pdf</code> in the project folder, then reload this page.
        </div>
      )}
      {items && (
        <ul className={compact ? 'space-y-1.5' : 'space-y-2'}>
          {(compact ? items.filter((i) => i.master) : items).map((i) => (
            <li key={i.file} className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5 text-sm">
              <div>
                <a className="font-medium text-brand-700 hover:underline dark:text-indigo-300" href={i.file} download>
                  {i.title}
                </a>
                {!compact && <div className="text-xs text-slate-500">{i.description}</div>}
              </div>
              <div className="whitespace-nowrap text-xs text-slate-500">{i.pages} pages · {mb(i.bytes)}</div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
